const STRICT_TRANSPORT_SECURITY = 'max-age=31536000; includeSubDomains'

function isLocalHostname(hostname: string) {
  return hostname === 'localhost' ||
    hostname.endsWith('.localhost') ||
    hostname === '127.0.0.1' ||
    hostname === '0.0.0.0' ||
    hostname === '[::1]'
}

function trySetHeader(response: Response, name: string, value: string) {
  try {
    response.headers.set(name, value)
    return response
  } catch {
    const headers = new Headers(response.headers)
    headers.set(name, value)
    return new Response(response.body, {
      headers,
      status: response.status,
      statusText: response.statusText,
    })
  }
}

export function redirectInsecureRequest(request: Request) {
  const url = new URL(request.url)
  if (url.protocol !== 'http:' || isLocalHostname(url.hostname)) return null

  url.protocol = 'https:'
  return new Response(null, {
    status: 308,
    headers: {
      'Cache-Control': 'no-store',
      Location: url.toString(),
    },
  })
}

export function withDocumentNoStore(response: Response) {
  const contentType = response.headers.get('Content-Type') ?? ''
  if (!contentType.toLowerCase().includes('text/html')) return response

  return trySetHeader(response, 'Cache-Control', 'no-store')
}

export function withHttpsSecurityHeaders(request: Request, response: Response) {
  const url = new URL(request.url)
  if (url.protocol !== 'https:' || isLocalHostname(url.hostname)) return response

  return trySetHeader(response, 'Strict-Transport-Security', STRICT_TRANSPORT_SECURITY)
}

export function withWorkerResponseHeaders(request: Request, response: Response) {
  return withHttpsSecurityHeaders(request, withDocumentNoStore(response))
}

import { createRequestHandler } from 'react-router'
import { dispatchApiRequest } from '@/app/server/apiRouter'
import { redirectInsecureRequest, withWorkerResponseHeaders } from './responseHeaders'

declare module 'react-router' {
  interface AppLoadContext {
    cloudflare: {
      env: CloudflareEnv
      ctx: ExecutionContext
    }
  }
}

const requestHandler = createRequestHandler(
  () => import('virtual:react-router/server-build') as Promise<any>,
  process.env.NODE_ENV ?? 'production',
)

export default {
  async fetch(request, env, ctx) {
    const httpsRedirect = redirectInsecureRequest(request)
    if (httpsRedirect) return httpsRedirect

    const apiResponse = await dispatchApiRequest(request)
    if (apiResponse) return withWorkerResponseHeaders(request, apiResponse)

    const response = await requestHandler(request, {
      cloudflare: { env, ctx },
    })
    return withWorkerResponseHeaders(request, response)
  },
} satisfies ExportedHandler<CloudflareEnv>

import { describe, expect, it } from 'vitest'
import {
  redirectInsecureRequest,
  withDocumentNoStore,
  withHttpsSecurityHeaders,
  withWorkerResponseHeaders,
} from './responseHeaders'

describe('worker response headers', () => {
  it('redirects public HTTP requests to HTTPS without caching the redirect', () => {
    const response = redirectInsecureRequest(
      new Request('http://nocards.app/api/auth/login/google?next=%2Fcards'),
    )

    expect(response?.status).toBe(308)
    expect(response?.headers.get('Location')).toBe('https://nocards.app/api/auth/login/google?next=%2Fcards')
    expect(response?.headers.get('Cache-Control')).toBe('no-store')
  })

  it('does not redirect HTTPS or local development HTTP requests', () => {
    expect(redirectInsecureRequest(new Request('https://nocards.app/'))).toBeNull()
    expect(redirectInsecureRequest(new Request('http://localhost:8787/'))).toBeNull()
  })

  it('marks HTML responses as no-store at the worker boundary', async () => {
    const response = withDocumentNoStore(
      new Response('<!doctype html>', {
        headers: { 'Content-Type': 'text/html; charset=utf-8' },
      }),
    )

    expect(response.headers.get('Cache-Control')).toBe('no-store')
    await expect(response.text()).resolves.toBe('<!doctype html>')
  })

  it('leaves non-document responses alone', () => {
    const response = new Response('{}', {
      headers: { 'Content-Type': 'application/json', 'Cache-Control': 'max-age=60' },
    })

    expect(withDocumentNoStore(response)).toBe(response)
  })

  it('adds HSTS to HTTPS responses', () => {
    const response = withHttpsSecurityHeaders(
      new Request('https://nocards.app/api/auth/session'),
      Response.json({ ok: true }),
    )

    expect(response.headers.get('Strict-Transport-Security')).toBe('max-age=31536000; includeSubDomains')
  })

  it('does not add HSTS to local development responses', () => {
    const response = new Response('ok')

    expect(withHttpsSecurityHeaders(new Request('http://localhost:8787/'), response)).toBe(response)
    expect(response.headers.get('Strict-Transport-Security')).toBeNull()
  })

  it('applies document cache and HTTPS security headers together', () => {
    const response = withWorkerResponseHeaders(
      new Request('https://nocards.app/'),
      new Response('<!doctype html>', {
        headers: { 'Content-Type': 'text/html' },
      }),
    )

    expect(response.headers.get('Cache-Control')).toBe('no-store')
    expect(response.headers.get('Strict-Transport-Security')).toBe('max-age=31536000; includeSubDomains')
  })
})

